import {createTeamTools} from './team-tools.js';
import {salonDateParts} from './api.js';
import {createSupportUI} from './support-ui.js';
import {createClientPortal} from './client.js';
import {durationMinutes,minutesOf,formatTime,collisionFor,availableSlots} from './scheduling.js';
import {api,config} from './api.js';
import {today} from './data.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2m2 10h3m4 0h3m-10 4h3',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',paw:'M9 15c-2 3-3 5-1 6 2 1 3-1 4-1s3 2 5 1c2-1 1-4-1-6-2-2-5-2-7 0M7 6c0 3-4 4-4 1s4-4 4-1m5-3c0 3-4 3-4 0s4-3 4 0m5 0c0 3-4 3-4 0s4-3 4 0m4 5c0 3-4 3-4 0s4-3 4 0',users:'M16 21v-2c0-3-2-5-5-5H8c-3 0-5 2-5 5v2m13-15a4 4 0 0 1 0 8m5 7v-2a5 5 0 0 0-3-4M8 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',scissors:'m8 8 12 12M8 16 20 4M6 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6m0 12a3 3 0 1 0 0 6 3 3 0 0 0 0-6',box:'m3 7 9-4 9 4-9 4-9-4m0 0v12l9 4 9-4V7M12 11v12m-5-18 10 4',chart:'M4 20V10m8 10V4m8 16v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-5h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 8l2-4 3 1 3-1z',search:'m21 21-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',clock:'M12 7v5l3 2m-3-12a10 10 0 1 0 0 20 10 10 0 0 0 0-20',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5l-2 4m5 3h4',check:'m5 12 4 4L19 6',heart:'M12 21C-8 9 5-4 12 5c7-9 20 4 0 16',print:'M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v7H7z',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const money=n=>Number(n||0).toLocaleString('ru-RU')+' ₽';
const entry=new URLSearchParams(location.search);if(!entry.has('app')&&location.pathname.includes('/studio/'))entry.set('app','studio');
const state={portal:entry.get('app')==='studio'?'studio':'client',page:'calendar',date:today(),view:'day',role:entry.get('app')==='studio'?(entry.get('role')==='master'?'master':'admin'):'client',userId:11,query:'',data:{},loading:true};
const statuses={pending:['Ждёт подтверждения','amber'],confirmed:['Подтверждено','green'],completed:['Завершено',''],cancelled:['Отменено','']};
const nav=[['calendar','calendar','Расписание'],['queue','bell','Заявки'],['tasks','check','Задачи смены'],['support','heart','Поддержка'],['clients','users','Клиенты'],['pets','paw','Питомцы'],['team','users','Команда'],['work-schedules','clock','Графики'],['services','scissors','Услуги'],['storage','box','Склад'],['analytics','chart','Обзор'],['access','users','Доступы'],['settings','settings','Настройки']];
const find=(r,id)=>state.data[r]?.find(x=>x[({pets:'pet_id',users:'user_id',services:'service_id',breeds:'breed_id',book:'book_id'})[r]]===id)||{};
const pet=b=>find('pets',b.pet_id),service=b=>find('services',b.service_id),owner=p=>find('users',p.owner_id),breed=p=>find('breeds',p.breed_id).title||'Порода не указана';
const image=p=>'/assets/pets/'+(p.image||'maltipoo')+'.webp';
const fullname=u=>[u.name,u.surname].filter(Boolean).join(' ')||'Не указан';
const duration=durationMinutes,minutes=minutesOf,time=formatTime;
const masters=()=>(state.data.masters||state.data.users)?.filter(u=>['master','employee','groomer'].includes(u.role))||[];
const visibleMasters=()=>state.role==='master'?(config.mode==='demo'?masters().slice(0,1):masters().filter(u=>u.user_id===state.userId)):masters();
const bookings=()=>state.data.book?.filter(b=>b.status!=='cancelled'&&b.date===state.date&&(state.role!=='master'||b.master_id===visibleMasters()[0]?.user_id)&&(state.role!=='client'||pet(b).owner_id===state.userId))||[];
const matching=b=>(pet(b).name+' '+breed(pet(b))+' '+fullname(owner(pet(b)))+' '+service(b).title).toLowerCase().includes(state.query.toLowerCase());
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
let loadSequence=0;
async function load(){
 const sequence=++loadSequence;state.loading=true;state.error='';render();
 try{
  let me=null;
  if(config.mode==='live'){
   me=await api.get('users',Number(sessionStorage.getItem('mimiroom-user')));state.userId=me.user_id;state.me=me;
   state.role=me.role==='admin'?'admin':me.role==='manager'?'manager':me.role==='groomer'?'master':'client';
  }
  const staff=state.portal==='studio'&&state.role!=='client';
  const management=['admin','manager'].includes(state.role);
  const keys=['breeds','services','masters',...(config.mode==='demo'||staff?['pets']:[]),...(staff&&management?['users','storages','measure-units']:[]),...(staff?['work-schedules']:[])];
  const out=await Promise.all(keys.map(async key=>[key,await api.list(key,key==='work-schedules'&&state.role==='master'?{master_id:state.userId}:{})]));
  const bookFilters=config.mode==='live'?(state.portal==='client'||state.role==='client'?{client_id:state.userId}:state.role==='master'?{master_id:state.userId}:{}):{};
  const books=await api.list('book',bookFilters);
  if(sequence!==loadSequence)return;
  state.data=Object.fromEntries(out);state.data.book=books;
  if(config.mode==='live'&&state.portal==='client')state.data.pets=me.pets||[];
  let users=state.data.users||[];
  if(config.mode==='demo')users=await api.list('users');
  state.data.users=[...new Map([...users,...(state.data.masters||[]),...(me?[me]:[])].map(user=>[user.user_id,user])).values()];
  state.data.pets??=[];state.data.storages??=[];state.data['measure-units']??=[];state.data['work-schedules']??=[];
  if(!allowedPages().includes(state.page))state.page='calendar';state.error='';
 }catch(error){if(sequence!==loadSequence)return;state.error=error.message;state.data={users:[],masters:[],pets:[],breeds:[],services:[],book:[],storages:[],'measure-units':[],'work-schedules':[]};}
 state.loading=false;render();
}
function allowedPages(){return state.role==='client'?['calendar','pets','services','settings']:state.role==='master'?['calendar','queue','tasks','pets','services','work-schedules','settings']:nav.map(n=>n[0]).filter(id=>id!=='access'||state.role==='admin')}
function render(){if(state.portal==='client'){clientPortal.render();return}if(config.mode==='live'&&state.role==='client'&&!state.loading){$('#app').innerHTML='<div class="empty"><h3>Вход для команды</h3><p>Эта учётная запись предназначена для личного кабинета клиента.</p><a class="primary" href="?app=client">Открыть личный кабинет</a></div>';return}const title=nav.find(n=>n[0]===state.page)?.[2];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">МиМиРум<small>пространство заботы</small></div><div class="workspace"><i>${icon('paw')}</i><div><b>Студия МиМиРум</b><small>Санкт-Петербург</small></div></div><div class="nav-label">${state.role==='master'?'ЛИЧНОЕ ПРОСТРАНСТВО МАСТЕРА':'УПРАВЛЕНИЕ СТУДИЕЙ'}</div><nav class="nav">${nav.filter(n=>allowedPages().includes(n[0])).map(([id,ic,t])=>`<button data-page="${id}" class="${state.page===id?'active':''}">${icon(ic)}${t}${id==='calendar'?`<span>${bookings().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><a class="portal-link" href="?app=client">${icon('heart')} Клиентское приложение ↗</a><div class="demo-note"><b>${config.mode==='demo'?'◌ Демо-пространство':'● Подключено к API'}</b>${config.mode==='demo'?'Пример данных. Можно создавать записи и изучать систему.':'Данные загружаются с вашего сервера.'}</div><div class="profile"><div class="avatar">${state.role==='master'?'АС':state.role==='client'?'ЕМ':'Д'}</div><div><b>${esc(config.mode==='live'?state.me?.name||'Мой профиль':state.role==='master'?'Анастасия':'Екатерина')}</b><small>${state.role==='master'?'Мастер':state.role==='manager'?'Менеджер':state.role==='client'?'Клиент':'Администратор'}</small></div></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="crumb">Рабочее пространство<span>/</span>${title}</div><div class="top-actions"><label class="search">${icon('search')}<input id="search" placeholder="Поиск по записям…" value="${esc(state.query)}" aria-label="Поиск"><span class="key">⌘ K</span></label>${config.mode==='demo'?`<select id="role" class="role-select" aria-label="Демо-роль"><option value="admin" ${['admin','manager'].includes(state.role)?'selected':''}>Администратор</option><option value="master" ${state.role==='master'?'selected':''}>Мастер</option></select>`:''}<button class="icon-btn" data-action="requests" aria-label="Новые заявки">${icon('bell')}</button><div class="avatar">М</div></div></header><div class="content">${state.loading?'<div class="loading">Собираем ваше пространство…</div>':state.error?`<div class="empty"><h3>Не удалось загрузить данные</h3><p>${esc(state.error)}</p><button class="primary" data-action="settings">Настроить подключение</button></div>`:pageContent()}<footer class="footer-note"><span>МиМиРум · Всё для тех, кто заботится.</span><span>${config.mode==='demo'?'Демонстрационные данные · Изменения сохраняются в этом браузере':'API v0.0.1 · Данные вашего сервера'}</span></footer></div></main></div>`;bind();bindOperations();teamTools.bind();supportUI.mount();supportUI.bindInbox()}
function head(kicker,title,sub,button='Новая запись',action='new'){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${button?`<button class="primary" data-action="${action}">${icon('plus')}${button}</button>`:''}</div>`}
function pageContent(){switch(state.page){case'calendar':return calendar();case'queue':return queuePage();case'tasks':return tasksPage();case'support':return supportUI.inbox();case'pets':return petsPage();case'clients':return clientsPage();case'access':return teamTools.accessPage();case'team':return teamTools.teamPage();case'work-schedules':return teamTools.schedulesPage();case'services':return servicesPage();case'storage':return storagePage();case'analytics':return analyticsPage();default:return settingsPage()}}
function stats(){const bs=bookings(),revenue=bs.reduce((a,b)=>a+Number(service(b).price||0),0),mins=bs.reduce((a,b)=>a+duration(service(b)),0),occ=Math.round(mins/Math.max(1,visibleMasters().length*540)*100);return `<div class="stats">${[['Записи на день',bs.length,`${new Set(bs.map(b=>b.pet_id)).size} питомцев ждут заботы`,'calendar'],['Стоимость записей',money(revenue),'План по выбранному дню','chart'],['Загрузка команды',`${occ}%`,'Из 9 рабочих часов на мастера','clock'],['Новые заявки',bs.filter(b=>b.status==='pending').length,'Ожидают вашего подтверждения','heart']].map(([t,n,s,i])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><strong>${n}</strong><small>${s}</small><svg class="spark" viewBox="0 0 70 35"><path d="M1 29 12 24 22 27 32 15 43 19 54 8 67 3" fill="none" stroke-width="1.5"/></svg></div>`).join('')}</div>`}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function calendar(){const bs=bookings().filter(matching),ms=visibleMasters();return head('КАЖДЫЙ ВИЗИТ — С ЗАБОТОЙ',state.role==='master'?'Моя <em>смена.</em>':'Хороший день для <em>заботы.</em>',`${new Date(state.date+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})} · ${state.role==='master'?'Ваше личное расписание':'Всё важное — в одном пространстве.'}`)+stats()+`<div class="schedule-layout"><section class="panel"><div class="panel-title"><h2>${state.role==='client'?'Мои записи':'Расписание'}</h2><button class="text-btn" data-action="print">${icon('print')} Экспорт в PDF</button></div><div class="calendar-tools"><div class="date-nav"><button data-date-shift="-1" aria-label="Предыдущий день">‹</button><input type="date" id="date" value="${state.date}" aria-label="Дата расписания"><button data-date-shift="1" aria-label="Следующий день">›</button><button class="text-btn" data-action="today">Сегодня</button></div><div class="segment"><button data-view="day" class="${state.view==='day'?'selected':''}">День</button><button data-view="list" class="${state.view==='list'?'selected':''}">Список</button></div></div><div class="week-strip">${Array.from({length:7},(_,i)=>{let d=new Date(state.date+'T12:00:00');const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd+i);const ds=d.toLocaleDateString('sv-SE');return `<button class="day ${ds===state.date?'selected':''}" data-day="${ds}"><span>${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}</span><b>${d.getDate()}</b><i></i></button>`}).join('')}</div>${state.view==='list'||state.role==='client'?bookingTable(bs):ms.length?timeline(ms,bs):'<div class="empty">Нет мастеров с ролью master, employee или groomer. Проверьте роли пользователей на сервере.</div>'}<div class="legend"><span><i></i>Подтверждено</span><span><i style="background:#a67b94"></i>В процессе</span><span><i style="background:#d1b27c"></i>Новая заявка</span><span><i style="background:#c8bab0"></i>Завершено</span></div></section><aside class="right-rail"><div class="care-card"><div class="eyebrow">МАЛЕНЬКИЕ ДЕТАЛИ</div><h3>Большая любовь.<br>В каждой заботе.</h3><p>Пусть каждый гость почувствует себя дома.</p><img src="/assets/pets/maltipoo.webp" alt="Мальтипу"></div><section class="panel"><div class="rail-title"><h3>Ждут подтверждения</h3><span class="pill amber">${bookings().filter(b=>b.status==='pending').length}</span></div>${bookings().filter(b=>b.status==='pending').slice(0,3).map(b=>`<button class="request" data-book="${b.book_id}"><div class="pet-row"><img src="${image(pet(b))}" alt=""><div><b>${esc(pet(b).name)}</b><small>${esc(breed(pet(b)))}</small></div></div><div class="request-bottom"><span>${b.time.slice(0,5)} · ${esc(service(b).title)}</span><span>↗</span></div></button>`).join('')||'<p class="sub" style="padding:10px 16px 20px">Все заявки разобраны ♡</p>'}</section><section class="panel"><div class="rail-title"><h3>Загрузка мастеров</h3>${icon('clock')}</div><div class="occupancy">${ms.map(m=>{const n=Math.round(bs.filter(b=>b.master_id===m.user_id).reduce((a,b)=>a+duration(service(b)),0)/540*100);return `<div><p><span>${esc(m.name)}</span><span>${n}%</span></p><div class="bar"><i style="width:${Math.min(n,100)}%"></i></div></div>`}).join('')}</div></section></aside></div>`}
function scheduleRange(){
 if(config.mode==='demo')return {start:600,end:1140,hours:9};
 const weekday=(new Date(state.date+'T12:00').getDay()+6)%7;
 const shifts=(state.data['work-schedules']||[]).filter(x=>x.weekday===weekday&&!x.is_day_off);
 const starts=[...shifts.map(x=>minutes(x.start_time)),...bookings().map(x=>minutes(x.time))];
 const ends=[...shifts.map(x=>minutes(x.end_time)),...bookings().map(x=>x.end_time?minutes(salonDateParts(x.end_time).time):minutes(x.time)+duration(service(x)))];
 const start=starts.length?Math.floor(Math.min(...starts)/60)*60:540,end=ends.length?Math.ceil(Math.max(...ends)/60)*60:1260;
 return {start,end,hours:Math.max(1,(end-start)/60)};
}
function timeline(ms,bs){const scale=innerWidth>=1550?80:70,range=scheduleRange();return `<div class="timeline-scroll"><div class="timeline" style="--cols:${ms.length}"><div class="master-row"><div></div>${ms.map((m,i)=>`<div class="master"><div class="avatar" style="background:${['#e5d3cb','#ded7e4','#e4ddcc'][i%3]}">${esc((m.name||'')[0]||'М')}${esc((m.surname||'')[0]||'')}</div><div><b>${esc(fullname(m))}</b><small>Грумер · ${bs.filter(b=>b.master_id===m.user_id).length} записи</small></div></div>`).join('')}</div><div class="time-grid" style="height:${scale*range.hours}px"><div class="times">${Array.from({length:range.hours},(_,i)=>`<span class="time-label" style="top:${i*scale}px">${time(range.start+i*60)}</span>`).join('')}</div>${ms.map(m=>`<div class="master-lane" data-lane="${m.user_id}">${bs.filter(b=>b.master_id===m.user_id).map(b=>{const start=minutes(b.time),s=service(b),h=(b.end_time?(Date.parse(b.end_time)-Date.parse(b.start_time))/60000:duration(s))*scale/60;return `<button class="slot ${esc(b.status||'confirmed')}" style="top:${(start-range.start)*scale/60}px;height:${Math.max(33,h-7)}px" data-book="${b.book_id}"><div class="slot-time"><span>${b.time.slice(0,5)} — ${time(start+duration(s))}</span><span>${b.status==='completed'?'✓':'·'}</span></div>${h>65?`<img src="${image(pet(b))}" alt="">`:''}<strong>${esc(pet(b).name||'Питомец')}</strong>${h>65?`<small>${esc(breed(pet(b)))}</small><small>${esc(s.title)}</small>`:''}${h>105?`<div class="price">${money(s.price)}${b.status==='active'?' · В процессе':''}</div>`:''}</button>`}).join('')}${config.mode==='demo'&&!bs.some(b=>b.master_id===m.user_id&&minutes(b.time)<960&&minutes(b.time)+duration(service(b))>900)?`<button class="free-slot" style="top:${5*scale}px" data-slot-master="${m.user_id}" data-slot-time="15:00">+ Свободное окно</button>`:''}</div>`).join('')}${state.date===today()?`<div class="now-line" style="top:${Math.max(0,Math.min(range.hours*scale,(minutes(new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour12:false}))-range.start)*scale/60))}px"></div>`:''}</div></div></div>`}
function bookingTable(bs){return bs.length?`<div class="table-wrap"><table><thead><tr><th>ВРЕМЯ</th><th>ПИТОМЕЦ</th><th>УСЛУГА</th><th>МАСТЕР</th><th>СТОИМОСТЬ</th><th></th></tr></thead><tbody>${bs.sort((a,b)=>a.time.localeCompare(b.time)).map(b=>`<tr><td>${b.time.slice(0,5)}</td><td><div class="pet-row"><img src="${image(pet(b))}" alt=""><div><b>${esc(pet(b).name)}</b><small>${esc(breed(pet(b)))}</small></div></div></td><td>${esc(service(b).title)}</td><td>${esc(find('users',b.master_id).name)}</td><td>${money(service(b).price)}</td><td><button class="text-btn" data-book="${b.book_id}">Открыть ↗</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('calendar')}<h3>День открыт для заботы</h3><p>На выбранную дату записей пока нет.</p><button class="primary" data-action="new">Создать запись</button></div>`}
function petsPage(){const ps=(state.data.pets||[]).filter(p=>(state.role!=='client'||p.owner_id===state.userId)&&(state.role!=='master'||state.data.book.some(b=>b.pet_id===p.pet_id&&b.master_id===visibleMasters()[0]?.user_id))&&(p.name+' '+breed(p)).toLowerCase().includes(state.query.toLowerCase()));return head('ЗНАКОМЫЕ МОРДОЧКИ','Наши <em>гости.</em>','Карточки питомцев, владельцы и история заботы.','Добавить питомца','new-pet')+`<div class="card-grid">${ps.map(p=>`<button class="pet-card" data-pet="${p.pet_id}"><img src="${image(p)}" alt="${esc(p.name)}"><div style="display:flex;justify-content:space-between"><h3>${esc(p.name)}</h3><span class="pill">${state.data.book.filter(b=>b.pet_id===p.pet_id).length} визита</span></div><p>${esc(breed(p))}</p><p>${esc(fullname(owner(p)))} ↗</p></button>`).join('')}</div>`}
function clientsPage(){const us=state.data.users.filter(u=>u.role==='client'&&fullname(u).toLowerCase().includes(state.query.toLowerCase()));return head('ЛЮДИ, КОТОРЫЕ ДОВЕРЯЮТ','Наши <em>клиенты.</em>','Владельцы питомцев и их история визитов.',state.role==='admin'?'Добавить клиента':null,'new-client')+`<div class="panel table-wrap"><table><thead><tr><th>КЛИЕНТ</th><th>ПИТОМЦЫ</th><th>ВИЗИТЫ</th><th></th></tr></thead><tbody>${us.map(u=>{const ps=state.data.pets.filter(p=>p.owner_id===u.user_id);return `<tr><td>${esc(fullname(u))}</td><td>${ps.map(p=>esc(p.name)).join(', ')||'Пока нет'}</td><td>${state.data.book.filter(b=>ps.some(p=>p.pet_id===b.pet_id)).length}</td><td><button class="text-btn" data-client="${u.user_id}">Карточка ↗</button></td></tr>`}).join('')}</tbody></table></div>`}
function teamPage(){return head('ВМЕСТЕ — ЛУЧШЕ','Команда <em>заботы.</em>','Расписание и загрузка мастеров на выбранный день.',null)+`<div class="card-grid">${masters().map((u,i)=>`<div class="panel service-card"><div class="avatar" style="width:52px;height:52px;font-size:18px">${esc(u.name[0])}${esc(u.surname[0])}</div><h3>${esc(fullname(u))}</h3><span class="pill green">Грумер</span><p class="sub">${state.data.book.filter(b=>b.master_id===u.user_id&&b.date===state.date).length} записи · ${dateLabel(state.date)}</p><button class="secondary" data-master="${u.user_id}">Записать к мастеру ${icon('arrow')}</button></div>`).join('')}</div>`}
function servicesPage(){return head('ПРОДУМАНО ДО МЕЛОЧЕЙ','Красота и <em>комфорт.</em>','Каталог услуг, длительность процедур и стоимость.',['admin','manager'].includes(state.role)?'Добавить услугу':null,'new-service')+`<div class="card-grid">${state.data.services.filter(s=>s.title.toLowerCase().includes(state.query.toLowerCase())).map(s=>`<div class="panel service-card">${icon('scissors')}<h3>${esc(s.title)}</h3><p class="sub">${duration(s)} минут · ${s.breed_id?esc(find('breeds',s.breed_id).title):'Для разных пород'}</p><strong>${money(s.price)}</strong><button class="secondary" data-service="${s.service_id}">${['admin','manager'].includes(state.role)?'Изменить услугу':'Записаться'} ${icon('arrow')}</button></div>`).join('')}</div>`}
function storagePage(){return head('ВСЁ ДЛЯ БЕРЕЖНОГО УХОДА','Порядок на <em>полках.</em>','Остатки расходных материалов. Нормы расхода задаются в услугах.','Добавить материал','new-storage')+`<div class="panel table-wrap"><table><thead><tr><th>МАТЕРИАЛ</th><th>ОСТАТОК</th><th>ЕДИНИЦА</th><th></th></tr></thead><tbody>${state.data.storages.filter(s=>(s.title||'').toLowerCase().includes(state.query.toLowerCase())).map(s=>`<tr><td>${esc(s.title)}</td><td><span class="pill ${s.count<200?'amber':'green'}">${s.count??'—'}</span></td><td>${esc(state.data['measure-units'].find(u=>u.measure_unit_id===s.measure_unit_id)?.title||'—')}</td><td><button class="text-btn" data-storage="${s.item_id}">Изменить ↗</button></td></tr>`).join('')}</tbody></table></div><p class="sub">Цветовой ориентир в демо: менее 200 единиц. Резервирование материалов выполняет сервер.</p>`}
function analyticsPage(){return head('БИЗНЕС В ДЕТАЛЯХ','Ясная <em>картина.</em>','Обзор записей за '+dateLabel(state.date)+'. Стоимость записей не является фактической выручкой.',null)+stats()+`<div class="settings-grid"><section class="panel settings-card"><h2>Популярные услуги</h2>${state.data.services.map(s=>{const count=bookings().filter(b=>b.service_id===s.service_id).length;return `<div class="feature-line"><span>${esc(s.title)}</span><b>${count} записей</b></div>`}).join('')}</section><section class="panel settings-card"><h2>Повторные гости</h2><p>Питомцы с двумя и более записями в загруженных данных.</p>${state.data.pets.filter(p=>state.data.book.filter(b=>b.pet_id===p.pet_id).length>1).map(p=>`<button class="request" data-pet="${p.pet_id}"><div class="pet-row"><img src="${image(p)}" alt=""><div><b>${esc(p.name)}</b><small>${esc(breed(p))}</small></div></div></button>`).join('')||'<p>Пока нет повторных записей.</p>'}</section></div>`}
function settingsPage(){return head('ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО','Всё на <em>своих местах.</em>','Подключение, режим работы и возможности расширения.',null)+`<div class="settings-grid"><section class="panel settings-card"><h2>Подключение к бэкенду</h2><p>API v0.0.1 из вашей спецификации. По умолчанию используется подключение студии. Для другого сервера укажите его адрес и войдите в свою учётную запись.</p><form id="connect-form"><label class="field">Адрес API (пусто — подключение студии)<input name="base" type="url" placeholder="https://api.example.ru" value="${esc(config.base)}"></label><div class="form-grid"><label class="field">Логин<input name="username" autocomplete="username" required></label><label class="field">Пароль<input name="password" type="password" autocomplete="current-password" required></label></div><div class="error" id="connect-error"></div><button class="primary" type="submit">Войти и подключить ${icon('arrow')}</button></form>${config.mode==='live'?'<button class="secondary" data-action="logout" style="margin-top:15px">Выйти из API</button>':'<div class="notice">Сейчас открыт деморежим. Данные примера сохраняются только в этом браузере. Переключение ролей — демонстрация интерфейса.</div>'}</section><section class="panel settings-card"><h2>Рабочее пространство</h2><div class="settings-shortcuts"><button class="secondary" data-own-profile>Мой профиль и Telegram</button>${['admin','manager'].includes(state.role)?'<button class="secondary" data-slot-interval>Шаг свободных окошек</button>':''}</div>${[['Записи, питомцы, услуги','API подготовлен'],['Команда и клиенты','API подготовлен'],['Материалы и справочники','API подготовлен'],['Бронирования и статусы','Подключены'],['Профиль, телефон и Telegram','Подключены'],['Права и доступность слотов','Проверяет сервер']].map(([a,b])=>`<div class="feature-line"><span>${a}</span><span class="muted">${b}</span></div>`).join('')}<p>Данные API загружаются постранично, до 10 000 строк на раздел. Для больших баз нужна серверная фильтрация. Проверка прав выполняется сервером.</p>${config.mode==='demo'?'<button class="secondary" data-action="reset">Сбросить демоданные</button>':''}</section></div>`}
let previousFocus;
function drawer(title,body){previousFocus=document.activeElement;$('#overlay').innerHTML=`<div class="backdrop" data-close></div><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-header"><h2>${title}</h2><button data-close aria-label="Закрыть">×</button></div>${body}</section>`;document.body.style.overflow='hidden';$('#overlay').querySelectorAll('[data-close]').forEach(b=>b.onclick=close);setTimeout(()=>$('.drawer input,.drawer select,.drawer button')?.focus(),30)}
function close(){$('#overlay').innerHTML='';document.body.style.overflow='';previousFocus?.focus()}
const options=(items,field,label,selected)=>items.map(i=>`<option value="${i[field]}" ${String(i[field])===String(selected)?'selected':''}>${esc(typeof label==='function'?label(i):i[label])}</option>`).join('');
function statusPill(b){const s=statuses[b.status]||['Запись',''];return `<span class="pill ${s[1]}">${s[0]}</span>`}
function openBook(id){
 const b=find('book',Number(id)),p=pet(b),svc=service(b),canEdit=['admin','manager'].includes(state.role)||b.master_id===state.userId;
 drawer('Детали визита',`<div class="detail-hero"><img src="${image(p)}" alt=""><div><h3>${esc(p.name||'Гость студии')}</h3><p>${esc(breed(p))}</p>${statusPill(b)}</div></div><div class="detail-list"><div><span>Уход</span><b>${esc(svc.title)}</b></div><div><span>Когда</span><b>${dateLabel(b.date)} · ${b.time.slice(0,5)}${b.end_time?'–'+salonDateParts(b.end_time).time.slice(0,5):''}</b></div><div><span>Мастер</span><b>${esc(fullname(find('users',b.master_id)))}</b></div><div><span>Владелец</span><b>${esc(b.client_name||fullname(owner(p)))}</b></div>${b.client_phone?`<div><span>Телефон</span><b>${esc(b.client_phone)}</b></div>`:''}<div><span>Стоимость ухода</span><b>${money(svc.price)}</b></div></div>${b.comment?`<div class="notice">${esc(b.comment)}</div>`:''}<div class="form-actions">${canEdit?'<button class="secondary" id="edit-book">Изменить пожелания</button>':''}${canEdit&&['pending','confirmed'].includes(b.status)?`<button class="primary" id="status-book">${b.status==='pending'?'Подтвердить визит':'Завершить уход'}</button><button class="text-btn danger" id="cancel-book">Отменить визит</button>`:''}</div>${state.role==='admin'?'<button class="text-btn danger" id="delete-book" style="margin-top:25px">Удалить запись</button>':careChecklist(b)}`);
 if($('#edit-book'))$('#edit-book').onclick=()=>bookingForm(b);
 if($('#status-book'))$('#status-book').onclick=()=>advance(b.book_id);
 if($('#cancel-book'))$('#cancel-book').onclick=async()=>{try{await api.cancelBooking(b.book_id);close();await load();toast('Визит отменён; история сохранена')}catch(e){toast(e.message)}};
 bindCareChecklist(b);if($('#delete-book'))$('#delete-book').onclick=()=>confirmDelete('book',b.book_id,'Удалить запись?',`Визит будет удалён. Для обычной отмены используйте «Отменить визит»: это сохраняет историю.`);
}
function confirmDelete(resource,id,title,text){drawer(title,`<p class="sub">${esc(text)}</p><div class="form-actions"><button class="secondary" id="cancel-delete">Оставить</button><button class="primary" id="confirm-delete">Удалить</button></div><div id="form-error" class="error"></div>`);$('#cancel-delete').onclick=close;$('#confirm-delete').onclick=async()=>{try{await api.remove(resource,id);close();await load();toast('Запись удалена')}catch(e){$('#form-error').textContent=e.message}}}
function bookingForm(b={},preset={}){
 if(config.mode==='live'&&b.book_id){
  drawer('Пожелания к визиту',`<p class="sub">${dateLabel(b.date)} · ${b.time.slice(0,5)} · ${esc(service(b).title)}</p><form id="booking-form"><label class="field">Пожелания<textarea name="comment">${esc(b.comment||'')}</textarea></label><div class="notice">Для другого времени создайте новую запись и отдельно отмените прежнюю. Существующий визит сохранится до отмены.</div><div class="error" role="alert"></div><button class="primary" type="submit">Сохранить пожелания</button></form>`);
  $('#booking-form').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));submit(event.target,async()=>{await api.save('book',{comment:data.comment},b.book_id);close();await load();toast('Пожелания обновлены');});};return;
 }
 drawer(b.book_id?'Изменить запись':'Новая забота',`<form id="booking-form"><label class="field">Питомец<select name="pet_id"><option value="">Гость без карточки</option>${options(state.data.pets.filter(p=>state.role!=='client'||p.owner_id===state.userId),'pet_id',p=>p.name+' · '+breed(p),b.pet_id||preset.pet_id)}</select></label><button type="button" class="text-btn" id="add-pet-inline">+ Добавить питомца</button><div class="form-grid"><label class="field">Имя владельца<input name="client_name" value="${esc(b.client_name||'')}"></label><label class="field">Телефон<input name="client_phone" type="tel" value="${esc(b.client_phone||'')}"></label></div><label class="field">Услуга<select name="service_id" required>${options(state.data.services,'service_id',svc=>svc.title+' · '+money(svc.price),b.service_id||preset.service_id)}</select></label><label class="field">Мастер<select name="master_id" required>${options(visibleMasters(),'user_id',fullname,b.master_id||preset.master_id)}</select></label><div class="form-grid"><label class="field">Дата<input name="date" type="date" required value="${b.date||state.date}"></label><label class="field">Время<input name="time" type="time" required ${config.mode==='live'?'readonly':''} value="${config.mode==='demo'?b.time?.slice(0,5)||preset.time||'12:00':''}"></label></div><div id="available-slots" class="slot-picker" aria-live="polite"></div><label class="field">Пожелания<textarea name="comment">${esc(b.comment||'')}</textarea></label><div class="notice" id="booking-summary">Выберите свободное время.</div><div class="error" id="form-error" role="alert"></div><button class="primary" type="submit">${b.book_id?'Сохранить':'Создать запись'}</button></form>`);
 $('#add-pet-inline').onclick=()=>entityForm('pets',null,true);bindAvailableSlots(b);
 $('#booking-form').onsubmit=event=>{
  event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));for(const key of ['pet_id','master_id','service_id'])data[key]=Number(data[key])||null;
  const selectedPet=find('pets',data.pet_id),svc=find('services',data.service_id);
  if(!data.master_id||!data.service_id||!data.time){$('#form-error').textContent='Выберите услугу, мастера и окошко.';return;}
  if(!data.pet_id&&!data.client_name.trim()){ $('#form-error').textContent='Укажите питомца или имя владельца гостя.';return;}
  if(data.pet_id&&svc.breed_id&&svc.breed_id!==selectedPet.breed_id){$('#form-error').textContent='Эта услуга предназначена для другой породы.';return;}
  let payload;
  if(config.mode==='live'){
   const slot=(form.availableChoices||[]).find(x=>x.time.slice(0,5)===data.time&&x.master_id===data.master_id&&x.service_id===data.service_id);
   if(!slot){$('#form-error').textContent='Обновите список и выберите доступное время.';return;}
   payload={master_id:data.master_id,service_id:data.service_id,start_time:slot.start_time,pet_id:data.pet_id,client_id:selectedPet.owner_id||null,client_name:data.client_name.trim()||null,client_phone:data.client_phone.trim()||null,comment:data.comment};
  }else{
   const conflict=collisionFor({bookings:state.data.book,services:state.data.services,date:data.date,masterId:data.master_id,petId:data.pet_id,start:minutes(data.time),duration:duration(svc),excludeId:b.book_id});
   if(conflict){$('#form-error').textContent='Время уже занято. Выберите другое окно.';return;}
   payload={...data,time:data.time+':00',status:b.status||'pending'};
  }
  submit(form,async()=>{try{await api.save('book',payload,b.book_id);state.date=data.date;close();await load();toast('Запись сохранена ♡')}catch(error){if(error.status===409){form.elements.time.value='';form.refreshSlots?.();}throw error;}});
 };
}
async function submit(form,fn){const btn=form.querySelector('[type="submit"]');btn.disabled=true;try{await fn()}catch(e){const target=form.querySelector('.error');if(target)target.textContent=e.message;else toast(e.message)}finally{if(btn.isConnected)btn.disabled=false}}
function openPet(id){const p=find('pets',Number(id)),bs=state.data.book.filter(b=>b.pet_id===p.pet_id);drawer('Паспорт заботы',`<div class="detail-hero"><img src="${image(p)}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc(breed(p))}</p><span class="pill">${bs.length} визита</span></div></div><div class="detail-list"><div><span>Владелец</span><b>${esc(fullname(owner(p)))}</b></div><div><span>День рождения</span><b>${p.birthday?new Date(p.birthday+'T12:00').toLocaleDateString('ru-RU'):'Не указан'}</b></div></div><h3 class="section-title">История визитов</h3><button class="secondary" id="full-pet-history">Полная история ухода</button>${bs.sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<button class="request" data-history="${b.book_id}"><div style="display:flex;justify-content:space-between"><b>${esc(service(b).title)}</b><span>${money(service(b).price)}</span></div><p class="sub">${dateLabel(b.date)} · ${b.time.slice(0,5)} · ${esc(find('users',b.master_id).name)}</p></button>`).join('')||'<p class="sub">Первый визит ещё впереди.</p>'}<div class="form-actions"><button class="secondary" id="edit-pet">Изменить</button><button class="primary" id="book-pet">Записать на уход</button></div>`);$('#full-pet-history').onclick=()=>teamTools.history(p);$('#edit-pet').onclick=()=>entityForm('pets',p);$('#book-pet').onclick=()=>bookingForm({},{pet_id:p.pet_id});document.querySelectorAll('[data-history]').forEach(el=>el.onclick=()=>openBook(el.dataset.history))}
function entityForm(resource,item=null,after=false){if(resource==='services'){teamTools.serviceForm(item||{});return;}if(resource==='users'&&state.role==='manager'){toast('Менеджер может просматривать клиентов. Изменение доступно администратору.');return;}const isPet=resource==='pets',isUser=resource==='users',isService=resource==='services',id=item?.[isPet?'pet_id':isUser?'user_id':isService?'service_id':'item_id'];const field=(label,name,value='',type='text',required=true)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;let fields='';if(isPet)fields=field('Кличка','name',item?.name)+`<label class="field">Владелец<select name="owner_id" required>${options(state.data.users.filter(u=>u.role==='client'),'user_id',fullname,item?.owner_id)}</select></label><label class="field">Порода<select name="breed_id"><option value="">Не указана</option>${options(state.data.breeds,'breed_id','title',item?.breed_id)}</select></label>`+field('Дата рождения','birthday',item?.birthday,'date',false);else if(isUser)fields=field('Имя','name',item?.name)+field('Фамилия','surname',item?.surname)+field('Логин','login',item?.login)+field('Телефон','phone',item?.phone,'tel',false)+field('Email','email',item?.email,'email',false)+field(id?'Новый пароль (необязательно)':'Пароль (от 6 символов)','password','','password',!id);else if(isService)fields=field('Название','title',item?.title)+field('Стоимость, ₽','price',item?.price,'number')+field('Длительность, минут','duration_minutes',item?duration(item):90,'number');else fields=field('Материал','title',item?.title)+field('Остаток','count',item?.count??0,'number')+`<label class="field">Единица измерения<select name="measure_unit_id">${options(state.data['measure-units'],'measure_unit_id','title',item?.measure_unit_id)}</select></label>`;drawer(`${id?'Изменить':'Добавить'} ${isPet?'питомца':isUser?'клиента':isService?'услугу':'материал'}`,`<form id="entity-form">${fields}<div class="error" id="form-error" role="alert"></div><button class="primary" type="submit">Сохранить ${icon('check')}</button></form>`);$('#entity-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(isPet){d.owner_id=Number(d.owner_id);d.breed_id=d.breed_id?Number(d.breed_id):null;d.birthday=d.birthday||null}else if(isService){if(Number(d.price)<0||Number(d.duration_minutes)<=0){$('#form-error').textContent='Цена должна быть неотрицательной, длительность — больше нуля.';return}d.duration=`PT${Number(d.duration_minutes)}M`;delete d.duration_minutes;d.price=String(d.price)}else if(!isUser){d.count=Number(d.count);d.measure_unit_id=Number(d.measure_unit_id);if(d.count<0){$('#form-error').textContent='Остаток не может быть отрицательным.';return}}else{if(d.password&&d.password.length<6){$('#form-error').textContent='Пароль должен содержать минимум 6 символов.';return}if(!d.password)delete d.password;d.phone=d.phone||null;d.email=d.email||null;if(config.mode==='demo')d.role=item?.role||'client'}await submit(e.target,async()=>{const result=await api.save(resource,d,id);close();await load();toast('Сохранено');if(after)bookingForm({},{pet_id:result.pet_id})})}}
function openClient(id){const u=find('users',Number(id)),ps=state.data.pets.filter(p=>p.owner_id===u.user_id);drawer('Карточка клиента',`<h3 class="section-title">${esc(fullname(u))}</h3><p class="sub">${esc(u.login||'Владелец питомца')}</p><h3 class="section-title">Питомцы</h3>${ps.map(p=>`<button class="request" data-client-pet="${p.pet_id}"><div class="pet-row"><img src="${image(p)}" alt=""><div><b>${esc(p.name)}</b><small>${esc(breed(p))}</small></div></div></button>`).join('')||'<p class="sub">Питомцы ещё не добавлены.</p>'}${state.role==='admin'?'<button class="secondary" id="edit-client" style="margin-top:25px">Изменить данные</button>':''}${state.role==='admin'&&u.user_id!==state.userId?'<button class="secondary" id="edit-client-role">Роль и доступ</button>':''}`);$('#edit-client')?.addEventListener('click',()=>entityForm('users',u));$('#edit-client-role')?.addEventListener('click',()=>teamTools.roleForm(u));document.querySelectorAll('[data-client-pet]').forEach(el=>el.onclick=()=>openPet(el.dataset.clientPet))}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.query='';render()});$('#role')?.addEventListener('change',e=>{state.role=e.target.value;state.userId=state.role==='master'?1:11;if(!allowedPages().includes(state.page))state.page='calendar';render();toast('Демо: интерфейс '+{admin:'администратора',master:'мастера',client:'клиента'}[state.role])});$('#search').oninput=e=>{state.query=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start)};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBook(b.dataset.book));document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>openPet(b.dataset.pet));document.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.client));document.querySelectorAll('[data-master]').forEach(b=>b.onclick=()=>bookingForm({},{master_id:Number(b.dataset.master)}));document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>['admin','manager'].includes(state.role)?entityForm('services',find('services',Number(b.dataset.service))):bookingForm({},{service_id:Number(b.dataset.service)}));document.querySelectorAll('[data-storage]').forEach(b=>b.onclick=()=>entityForm('storages',state.data.storages.find(s=>s.item_id===Number(b.dataset.storage))));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.date=b.dataset.day;render()});document.querySelectorAll('[data-date-shift]').forEach(b=>b.onclick=()=>{const d=new Date(state.date+'T12:00');d.setDate(d.getDate()+Number(b.dataset.dateShift));state.date=d.toLocaleDateString('sv-SE');render()});document.querySelectorAll('[data-slot-master]').forEach(b=>b.onclick=()=>bookingForm({},{master_id:Number(b.dataset.slotMaster),time:b.dataset.slotTime}));$('#date')?.addEventListener('change',e=>{if(e.target.value){state.date=e.target.value;render()}});$('#connect-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const btn=e.target.querySelector('button');btn.disabled=true;try{await api.login(f.base,f.username,f.password);state.role='admin';await load();toast('Подключение установлено')}catch(err){$('#connect-error').textContent=err.message}finally{if(btn.isConnected)btn.disabled=false}})}
async function action(a){switch(a){case'new':bookingForm();break;case'new-pet':entityForm('pets');break;case'new-client':entityForm('users');break;case'new-service':teamTools.serviceForm();break;case'new-storage':entityForm('storages');break;case'menu':$('.sidebar').classList.toggle('open');break;case'print':window.print();break;case'today':state.date=today();render();break;case'settings':state.page='settings';render();break;case'requests':{const bs=bookings().filter(b=>b.status==='pending');if(bs.length)openBook(bs[0].book_id);else toast('Все заявки разобраны');break}case'reset':drawer('Начать демо заново?',`<p class="sub">Созданные вами демонстрационные записи будут заменены исходным примером.</p><button class="primary" id="reset-confirm" style="margin-top:25px">Сбросить демоданные</button>`);$('#reset-confirm').onclick=async()=>{api.reset();close();await load();toast('Демоданные восстановлены')};break;case'logout':try{await api.logout();await load();toast('Вы вышли из API')}catch(e){toast(e.message)}break}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search')?.focus()}if(e.key==='Tab'&&$('.drawer')){const els=[...$('.drawer').querySelectorAll('button,input,select,textarea,a')].filter(el=>!el.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const supportUI=createSupportUI({state,config,esc,icon,toast,renderApp:()=>render(),startBooking:()=>clientPortal.start()});
const clientPortal=createClientPortal({state,api,config,esc,icon,money,find,image,breed,fullname,drawer,close,toast,load,login:portalLogin,profile:()=>teamTools.profile(),history:p=>teamTools.history(p),mountSupport:()=>supportUI.mount()});
const teamTools=createTeamTools({state,api,config,esc,icon,money,fullname,drawer,close,toast,load,render});
load();

function bindAvailableSlots(existing={}){
 const form=$('#booking-form');let sequence=0;
 async function update(){
  const version=++sequence,data=Object.fromEntries(new FormData(form)),svc=find('services',Number(data.service_id));form.availableChoices=[];
  $('#booking-summary').textContent=`${svc.title||'Уход'} · ${duration(svc)} мин · ${money(svc.price)}`;
  if(config.mode==='live'){
   const target=$('#available-slots');target.innerHTML='<div class="loading">Ищем окошки…</div>';
   try{const slots=await api.availableSlots({service_id:Number(data.service_id),master_id:Number(data.master_id),pet_id:Number(data.pet_id)||undefined,date_from:data.date,date_to:data.date});if(version!==sequence||!form.isConnected)return;form.availableChoices=slots.filter(x=>x.date===data.date&&Date.parse(x.start_time)>Date.now());target.innerHTML='<p>Свободные окошки студии</p><div>'+form.availableChoices.map(slot=>`<button type="button" data-pick-time="${slot.time.slice(0,5)}">${slot.time.slice(0,5)}</button>`).join('')+'</div>'+(form.availableChoices.length?'':'<small>Нет окошек. Выберите другую дату или мастера.</small>');}
   catch(error){if(version!==sequence||!form.isConnected)return;target.innerHTML='<p class="error">'+esc(error.message)+'</p><button type="button" id="retry-studio-slots">Повторить</button>';$('#retry-studio-slots').onclick=update;}
  }else{
   const slots=availableSlots({bookings:state.data.book,services:state.data.services,date:data.date,masterId:Number(data.master_id),petId:Number(data.pet_id),duration:duration(svc),excludeId:existing.book_id});
   $('#available-slots').innerHTML='<p>Свободное время в демо</p><div>'+slots.map(t=>`<button type="button" data-pick-time="${t}">${t}</button>`).join('')+'</div>';
  }
  document.querySelectorAll('[data-pick-time]').forEach(button=>button.onclick=()=>{form.elements.time.value=button.dataset.pickTime;document.querySelectorAll('[data-pick-time]').forEach(x=>x.classList.toggle('selected',x===button));});
 }
 form.refreshSlots=update;['pet_id','service_id','master_id','date'].forEach(name=>form.elements[name].addEventListener('change',()=>{if(config.mode==='live')form.elements.time.value='';update();}));update();
}
function portalLogin(register=false){
 drawer(register?'Рады знакомству':'Ваш личный кабинет',`<p class="sub">${register?'Создадим кабинет для ваших питомцев.':'Войдите в свой аккаунт МиМиРум.'}</p><form id="portal-login">${register?'<div class="form-grid"><label class="field">Имя<input name="name" required minlength="2" maxlength="255" autocomplete="given-name"></label><label class="field">Фамилия<input name="surname" required minlength="2" maxlength="255" autocomplete="family-name"></label></div>':''}<label class="field">Логин<input name="username" autocomplete="username" required minlength="3" maxlength="64"></label><label class="field">Пароль<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required minlength="6" maxlength="128"></label><div id="portal-login-error" class="error" role="alert"></div><button class="primary" type="submit">${register?'Создать кабинет':'Войти'}</button></form><button class="text-btn" id="switch-auth">${register?'Уже есть аккаунт? Войти':'Первый визит? Зарегистрироваться'}</button>${config.mode==='live'?'<button class="secondary" id="portal-logout">Выйти из аккаунта</button>':''}`);
 $('#switch-auth').onclick=()=>portalLogin(!register);
 $('#portal-login').onsubmit=event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));submit(form,async()=>{if(register)await api.register(config.base,{login:data.username,password:data.password,name:data.name,surname:data.surname});else await api.login(config.base,data.username,data.password);close();await load();toast('Рады вам ♡');});};
 $('#portal-logout')?.addEventListener('click',async()=>{try{await api.logout()}catch{}state.userId=11;state.role=state.portal==='client'?'client':'admin';close();await load();});
}
function queuePage(){
 const groups=[['pending','Новые заявки'],['confirmed','Подтверждены'],['completed','Завершены']];
 return head('ВНИМАНИЕ К КАЖДОЙ ВСТРЕЧЕ','Каждый визит <em>под контролем.</em>','Подтверждайте визиты и завершайте уход. Отмена сохраняет историю.','Новая запись')+`<div class="operations-toolbar"><label>Дата <input type="date" id="queue-date" value="${state.date}"></label><span class="pill">${dateLabel(state.date)}</span></div><div class="kanban kanban-three">${groups.map(([status,title])=>{const visits=bookings().filter(b=>b.status===status);return `<section class="kanban-column" data-stage="${status}"><header><h3>${title}</h3><span>${visits.length}</span></header><div class="kanban-cards">${visits.map(b=>`<article class="kanban-card" draggable="${status!=='completed'}" data-drag-book="${b.book_id}"><div class="kanban-time">${b.time.slice(0,5)}<span>${duration(service(b))} мин</span></div><button data-book="${b.book_id}" class="kanban-pet"><img src="${image(pet(b))}" alt=""><div><h4>${esc(pet(b).name||b.client_name||'Гость')}</h4><small>${esc(service(b).title)}</small></div></button><footer><span>${esc(find('users',b.master_id).name)}</span><b>${money(service(b).price)}</b></footer>${status!=='completed'?`<button class="kanban-next" data-next-book="${b.book_id}">${status==='pending'?'Подтвердить':'Завершить уход'} ${icon('arrow')}</button>`:'<span class="kanban-complete">✓ Уход завершён</span>'}</article>`).join('')||'<div class="kanban-empty">Пока нет визитов</div>'}</div></section>`;}).join('')}</div>`;
}
function taskKey(){return 'mimiroom-shift-tasks-v1'}
function readTasks(){try{return JSON.parse(localStorage.getItem(taskKey()))||[]}catch{return[]}}
function tasksPage(){const tasks=readTasks().filter(t=>t.date===state.date&&(['admin','manager'].includes(state.role)||!t.master||t.master===visibleMasters()[0]?.user_id));const done=tasks.filter(t=>t.done).length;return head('ДЕНЬ БЕЗ ЗАБЫТЫХ МЕЛОЧЕЙ',state.role==='master'?'Мой план <em>заботы.</em>':'Ритм <em>студии.</em>','Задачи смены, подготовка к визитам и короткие заметки.',null)+`<div class="operations-toolbar"><label>Смена <input type="date" id="task-date" value="${state.date}"></label><span class="pill green">${done} из ${tasks.length} выполнено</span></div><div class="tasks-layout"><section class="panel settings-card"><h2>Задачи на день</h2>${config.mode==='demo'?`<form id="add-shift-task"><input name="title" required maxlength="200" placeholder="Например, подготовить стол к первому гостю"><button class="primary" type="submit" aria-label="Добавить задачу">${icon('plus')}</button></form><div class="task-items">${tasks.map(t=>`<div class="task-item ${t.done?'completed':''}"><label><input type="checkbox" data-toggle-task="${t.id}" ${t.done?'checked':''}><span>${esc(t.title)}</span></label><button data-remove-task="${t.id}" aria-label="Удалить задачу">×</button></div>`).join('')||'<p class="sub">Добавьте первую задачу для спокойной смены.</p>'}</div>`:'<p class="sub">Общий журнал задач появится после добавления API задач и исполнителей.</p>'}<p class="local-caption">Демо: задачи хранятся в этом браузере и не отправляются другим сотрудникам.</p></section><section class="panel settings-card"><h2>Особое внимание</h2><p class="sub">Пожелания гостей в визитах выбранной смены.</p>${bookings().filter(b=>b.comment).map(b=>`<button class="attention-card" data-book="${b.book_id}"><div><b>${esc(pet(b).name)}</b><span>${b.time.slice(0,5)}</span></div><p>${esc(b.comment)}</p><small>${esc(find('users',b.master_id).name)} · ${esc(service(b).title)}</small></button>`).join('')||'<p class="sub" style="margin-top:25px">Особых пожеланий нет.</p>'}</section></div>`}
function bindOperations(){
 $('#queue-date')?.addEventListener('change',e=>{if(e.target.value){state.date=e.target.value;render()}});$('#task-date')?.addEventListener('change',e=>{if(e.target.value){state.date=e.target.value;render()}});
 document.querySelectorAll('[data-next-book]').forEach(el=>el.onclick=()=>advance(el.dataset.nextBook));
 let dragged=null;document.querySelectorAll('[data-drag-book]').forEach(el=>{el.ondragstart=e=>{dragged=Number(el.dataset.dragBook);e.dataTransfer.setData('text/plain',String(dragged));el.classList.add('dragging')};el.ondragend=()=>{dragged=null;el.classList.remove('dragging');document.querySelectorAll('.drag-over').forEach(c=>c.classList.remove('drag-over'))}});
 document.querySelectorAll('[data-stage]').forEach(el=>{el.ondragover=e=>{if(dragged){e.preventDefault();el.classList.add('drag-over')}};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=async e=>{e.preventDefault();el.classList.remove('drag-over');const b=find('book',dragged),order=['pending','confirmed','completed'];if(order.indexOf(el.dataset.stage)!==order.indexOf(b.status)+1){toast('Перемещайте визит на следующий этап по порядку');return}await advance(b.book_id)}});
 $('#add-shift-task')?.addEventListener('submit',e=>{e.preventDefault();const title=e.target.elements.title.value.trim();if(!title)return;const tasks=readTasks();tasks.push({id:crypto.randomUUID(),title,date:state.date,master:state.role==='master'?visibleMasters()[0]?.user_id:null,done:false});localStorage.setItem(taskKey(),JSON.stringify(tasks));render();$('#add-shift-task input').focus()});
 document.querySelectorAll('[data-toggle-task]').forEach(el=>el.onchange=()=>{const tasks=readTasks();tasks.find(t=>t.id===el.dataset.toggleTask).done=el.checked;localStorage.setItem(taskKey(),JSON.stringify(tasks));render()});document.querySelectorAll('[data-remove-task]').forEach(el=>el.onclick=()=>{localStorage.setItem(taskKey(),JSON.stringify(readTasks().filter(t=>t.id!==el.dataset.removeTask)));render()});
 document.querySelectorAll('[data-lane]').forEach(lane=>lane.addEventListener('click',e=>{if(e.target.closest('button')||state.role!=='admin')return;const rect=lane.getBoundingClientRect(),scale=innerWidth>=1550?80:70;const start=600+Math.floor((e.clientY-rect.top)/scale*2)*30;if(start>=600&&start<1140)bookingForm({},{master_id:Number(lane.dataset.lane),time:time(start)})}));
}
async function advance(id){const b=find('book',Number(id));if(!['pending','confirmed'].includes(b.status))return;try{if(b.status==='pending')await api.save('book',{status:'confirmed'},b.book_id);else await api.completeBooking(b.book_id);await load();toast(b.status==='pending'?'Заявка подтверждена':'Визит завершён')}catch(error){toast(error.message)}}
function careChecklist(b){if(config.mode!=='demo'||b.master_id!==visibleMasters()[0]?.user_id)return '';let saved={};try{saved=JSON.parse(localStorage.getItem('mimiroom-care-'+b.book_id))||{}}catch{}return `<h3 class="section-title">План ухода</h3><div class="care-checklist">${['Познакомиться и уточнить пожелания','Проверить состояние кожи и шерсти','Выполнить уход и проверить результат','Передать питомца и рекомендации'].map((t,i)=>`<label><input type="checkbox" data-care-step="${i}" ${saved[i]?'checked':''}>${t}</label>`).join('')}</div><label class="field">Заметка мастера<textarea id="master-note" placeholder="Что учесть при следующем уходе…">${esc(saved.note||'')}</textarea></label><button class="secondary" id="save-master-note">Сохранить заметку</button><p class="local-caption">Демонстрационный журнал мастера в этом браузере.</p>`}
function bindCareChecklist(b){document.querySelectorAll('[data-care-step]').forEach(el=>el.onchange=()=>{let saved={};try{saved=JSON.parse(localStorage.getItem('mimiroom-care-'+b.book_id))||{}}catch{}saved[el.dataset.careStep]=el.checked;localStorage.setItem('mimiroom-care-'+b.book_id,JSON.stringify(saved))});$('#save-master-note')?.addEventListener('click',()=>{let saved={};try{saved=JSON.parse(localStorage.getItem('mimiroom-care-'+b.book_id))||{}}catch{}saved.note=$('#master-note').value;localStorage.setItem('mimiroom-care-'+b.book_id,JSON.stringify(saved));toast('Заметка сохранена')})}
